-- =================================================================
--  Remove the duplicate properties created by the bulk finisher.
--  Run once in the Supabase SQL Editor.
--
--  Cause: publishRow() always INSERTed, and on the unique-slug collision a
--  re-run guarantees it appended a random suffix and inserted anyway. Every
--  duplicate below is the keeper's slug + a 4-character suffix.
--  The importer has been fixed to UPDATE in that case; this cleans up what
--  the old behaviour already wrote.
--
--  Rule: keep the OLDEST row of each name (it owns the clean slug and any
--  hand curation), but first adopt the larger photo set where a newer copy
--  imported more.
--
--  Review the SELECT at the bottom before and after.
-- =================================================================

BEGIN;

-- 1. Adopt the richer photo sets onto the rows being kept.
UPDATE properties SET photos = '["https://xjliwfmugylwxlrwyvmh.supabase.co/storage/v1/object/public/photos/import/9bb561a7-a0cd-46c0-991b-a99356d5696b/00-25-paseo-del-mar-a40ff45d.jpg", "https://xjliwfmugylwxlrwyvmh.supabase.co/storage/v1/object/public/photos/import/9bb561a7-a0cd-46c0-991b-a99356d5696b/01-25-paseo-del-mar-ff7c9043.jpg", "https://xjliwfmugylwxlrwyvmh.supabase.co/storage/v1/object/public/photos/import/9bb561a7-a0cd-46c0-991b-a99356d5696b/02-25-paseo-del-mar-b6f9100e.jpg", "https://xjliwfmugylwxlrwyvmh.supabase.co/storage/v1/object/public/photos/import/9bb561a7-a0cd-46c0-991b-a99356d5696b/03-25-paseo-del-mar-a3b75335.jpg", "https://xjliwfmugylwxlrwyvmh.supabase.co/storage/v1/object/public/photos/import/9bb561a7-a0cd-46c0-991b-a99356d5696b/04-25-paseo-del-mar-29c9f532.jpg", "https://xjliwfmugylwxlrwyvmh.supabase.co/storage/v1/object/public/photos/import/9bb561a7-a0cd-46c0-991b-a99356d5696b/05-25-paseo-del-mar-cad71bb2.jpg", "https://xjliwfmugylwxlrwyvmh.supabase.co/storage/v1/object/public/photos/import/9bb561a7-a0cd-46c0-991b-a99356d5696b/06-25-paseo-del-mar-77f1800e.jpg", "https://xjliwfmugylwxlrwyvmh.supabase.co/storage/v1/object/public/photos/import/9bb561a7-a0cd-46c0-991b-a99356d5696b/07-25-paseo-del-mar-e0505cc6.jpg", "https://xjliwfmugylwxlrwyvmh.supabase.co/storage/v1/object/public/photos/import/9bb561a7-a0cd-46c0-991b-a99356d5696b/08-25-paseo-del-mar-46e8ddf4.jpg", "https://xjliwfmugylwxlrwyvmh.supabase.co/storage/v1/object/public/photos/import/9bb561a7-a0cd-46c0-991b-a99356d5696b/09-25-paseo-del-mar-30226f65.jpg", "https://xjliwfmugylwxlrwyvmh.supabase.co/storage/v1/object/public/photos/import/9bb561a7-a0cd-46c0-991b-a99356d5696b/10-25-paseo-del-mar-1243c0bf.jpg", "https://xjliwfmugylwxlrwyvmh.supabase.co/storage/v1/object/public/photos/import/9bb561a7-a0cd-46c0-991b-a99356d5696b/11-25-paseo-del-mar-f2d043be.jpg", "https://xjliwfmugylwxlrwyvmh.supabase.co/storage/v1/object/public/photos/import/9bb561a7-a0cd-46c0-991b-a99356d5696b/12-25-paseo-d